CREATE TABLE `vista_pedidos_clientes` (
	`id_cliente` VARCHAR(1) NOT NULL COLLATE 'utf8mb4_unicode_ci',
	`nombre_cliente` VARCHAR(1) NULL COLLATE 'utf8mb4_unicode_ci',
