	`total_pedidos` BIGINT(21) NOT NULL,
	`unidades_vendidas` DECIMAL(32,0) NULL,
	`ventas_totales` DECIMAL(34,2) NULL,
	`ganancia_total` DECIMAL(34,2) NULL
) ENGINE=MyISAM;

DROP TABLE IF EXISTS `vista_pedidos_clientes`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vista_pedidos_clientes` AS select `c`.`id_cliente` AS `id_cliente`,`c`.`nombre_cliente` AS `nombre_cliente`,`c`.`segmento` AS `segmento`,count(distinct `pe`.`id_pedido`) AS `total_pedidos`,coalesce(round(sum(`d`.`ventas`),2),0.00) AS `ventas_totales` from ((`clientes` `c` left join `pedidos` `pe` on(`pe`.`id_cliente` = `c`.`id_cliente`)) left join `detalle_pedido` `d` on(`d`.`id_pedido` = `pe`.`id_pedido`)) group by `c`.`id_cliente`,`c`.`nombre_cliente`,`c`.`segmento`
;

DROP TABLE IF EXISTS `vista_productos_vendidos`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vista_productos_vendidos` AS select `p`.`id_producto` AS `id_producto`,`p`.`codigo_producto` AS `codigo_producto`,`p`.`nombre_producto` AS `nombre_producto`,`sc`.`subcategoria` AS `subcategoria`,`c`.`categoria` AS `categoria`,coalesce(sum(`d`.`cantidad`),0) AS `unidades_vendidas`,coalesce(round(sum(`d`.`ventas`),2),0.00) AS `ventas_totales`,coalesce(round(sum(`d`.`ganancia`),2),0.00) AS `ganancia_total` from (((`productos` `p` join `subcategorias` `sc` on(`sc`.`id_subcategoria` = `p`.`id_subcategoria`)) join `categorias` `c` on(`c`.`id_categoria` = `sc`.`id_categoria`)) left join `detalle_pedido` `d` on(`d`.`id_producto` = `p`.`id_producto`)) group by `p`.`id_producto`,`p`.`codigo_producto`,`p`.`nombre_producto`,`sc`.`subcategoria`,`c`.`categoria`
;

DROP TABLE IF EXISTS `vista_ventas_categoria`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vista_ventas_categoria` AS select `c`.`id_categoria` AS `id_categoria`,`c`.`categoria` AS `categoria`,count(0) AS `lineas_vendidas`,sum(`d`.`cantidad`) AS `unidades_vendidas`,round(sum(`d`.`ventas`),2) AS `ventas_totales`,round(sum(`d`.`ganancia`),2) AS `ganancia_total` from (((`detalle_pedido` `d` join `productos` `p` on(`p`.`id_producto` = `d`.`id_producto`)) join `subcategorias` `sc` on(`sc`.`id_subcategoria` = `p`.`id_subcategoria`)) join `categorias` `c` on(`c`.`id_categoria` = `sc`.`id_categoria`)) group by `c`.`id_categoria`,`c`.`categoria`
;

DROP TABLE IF EXISTS `vista_ventas_region`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vista_ventas_region` AS select `pe`.`region` AS `region`,count(distinct `pe`.`id_pedido`) AS `total_pedidos`,sum(`d`.`cantidad`) AS `unidades_vendidas`,round(sum(`d`.`ventas`),2) AS `ventas_totales`,round(sum(`d`.`ganancia`),2) AS `ganancia_total` from (`pedidos` `pe` join `detalle_pedido` `d` on(`d`.`id_pedido` = `pe`.`id_pedido`)) group by `pe`.`region`
;

